// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 先看 config/thresholds.json 是否给这个仓库配了值；没有配置（或文件缺失/非法）时
// 回退到 DefaultLowStockThreshold。每次调用都重新读文件，所以运维改完配置立即生效，
// 不需要重新构建。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(warehouse, loadThresholds())
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return isLowStock(warehouse, quantity, loadThresholds())
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
//
// 整次调用只读一次配置：既避免每个仓库重复读文件，也避免同一次判定里用到两份不同的配置。
func LowStockWarehouses(stock map[string]int) []string {
	thresholds := loadThresholds()
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if isLowStock(warehouse, quantity, thresholds) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// isLowStock 是「严格小于阈值」这条规则的唯一实现。
func isLowStock(warehouse string, quantity int, thresholds map[string]int) bool {
	return quantity < thresholdFor(warehouse, thresholds)
}

// thresholdFor 返回仓库在给定配置下的阈值，未配置时回退默认值。
func thresholdFor(warehouse string, thresholds map[string]int) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 config/thresholds.json，返回「仓库 → 阈值」。
//
// 文件不存在、读不到或整体不是合法 JSON 时返回 nil，调用方据此回退到默认值——
// 配置坏了不该让判定崩掉。单个条目不是整数（或为 null）时只跳过该条目，不影响其它仓库。
// 不缓存，保证改文件立即生效。
func loadThresholds() map[string]int {
	path := thresholdsFilePath()
	if path == "" {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil
	}
	thresholds := make(map[string]int, len(raw))
	for warehouse, value := range raw {
		var threshold *int
		if err := json.Unmarshal(value, &threshold); err != nil || threshold == nil {
			continue
		}
		thresholds[warehouse] = *threshold
	}
	return thresholds
}

// thresholdsFilePath 从当前工作目录逐级向上找 config/thresholds.json，返回第一个存在的路径。
//
// 向上找是为了同时兼容「从仓库根启动」和「go test 以包目录为工作目录」两种情形；
// 找到含 go.mod 的仓库根、或到达文件系统根还没找到，就返回空串，由调用方回退默认值。
// 在仓库根停下还能避免误读仓库外祖先目录里的同名配置。
func thresholdsFilePath() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		candidate := filepath.Join(dir, "config", "thresholds.json")
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return ""
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

